package view;
import bus.account.AccountBUS;import java.awt.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import model.account.AccountModels.AccountRow;import model.auth.AuthenticatedSession;import view.component.UIStyle;
final class AccountPanel extends JPanel{
 private final AuthenticatedSession session;private final AccountBUS bus;private final JTextField search=new JTextField();private final JComboBox<String> filter=new JComboBox<>(new String[]{"Tất cả trạng thái","HoatDong","Khoa","ChoKichHoat","ThuHoi"});private final DefaultTableModel model=new DefaultTableModel(new Object[]{"ID","Tên đăng nhập","Nhân viên","Vai trò","Trạng thái","Đăng nhập gần nhất","__row"},0){public boolean isCellEditable(int r,int c){return false;}};private final JTable table=new JTable(model);private final JPanel detail=new JPanel(new BorderLayout());private final JButton edit=new JButton("Chỉnh sửa"),toggle=new JButton("Khóa / mở khóa");private AccountRow hovered;
 AccountPanel(AuthenticatedSession s,AccountBUS b){session=s;bus=b;setLayout(new BorderLayout(0,16));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(25,28,30,28));add(heading(),BorderLayout.NORTH);add(card(),BorderLayout.CENTER);edit.addActionListener(e->{if(hovered!=null)open(hovered);});toggle.addActionListener(e->toggle());load();}
 void refreshData(){load();}
 private JPanel heading(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JPanel l=new JPanel();l.setOpaque(false);l.setLayout(new BoxLayout(l,BoxLayout.Y_AXIS));JLabel t=new JLabel("Quản lý tài khoản");t.setFont(new Font("Segoe UI",Font.BOLD,25));t.setForeground(MainFrame.TEXT);JLabel d=new JLabel("Danh sách gọn — rê chuột vào tài khoản để xem chi tiết.");d.setForeground(MainFrame.MUTED);l.add(t);l.add(d);JButton add=new JButton("+ Tạo tài khoản");UIStyle.primaryButton(add);add.addActionListener(e->{new AccountDialog(SwingUtilities.getWindowAncestor(this),session,bus,null).setVisible(true);load();});p.add(l,BorderLayout.WEST);p.add(add,BorderLayout.EAST);return p;}
 private JPanel card(){JPanel o=new JPanel(new BorderLayout(14,0));o.setOpaque(false);JPanel list=new JPanel(new BorderLayout(0,12));list.setBackground(Color.WHITE);list.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(16,16,16,16)));JPanel bar=new JPanel(new BorderLayout(8,0));bar.setOpaque(false);search.setPreferredSize(new Dimension(300,36));search.putClientProperty("JTextField.placeholderText","Tìm tên đăng nhập, nhân viên...");bar.add(search,BorderLayout.CENTER);bar.add(filter,BorderLayout.EAST);list.add(bar,BorderLayout.NORTH);UIStyle.table(table);table.setRowHeight(40);table.setAutoCreateRowSorter(true);table.getColumnModel().getColumn(6).setMinWidth(0);table.getColumnModel().getColumn(6).setMaxWidth(0);table.getColumnModel().getColumn(6).setWidth(0);table.addMouseMotionListener(new java.awt.event.MouseMotionAdapter(){public void mouseMoved(java.awt.event.MouseEvent e){int r=table.rowAtPoint(e.getPoint());if(r>=0)showDetail((AccountRow)table.getValueAt(table.convertRowIndexToModel(r),6));}});list.add(new JScrollPane(table),BorderLayout.CENTER);search.addActionListener(e->load());filter.addActionListener(e->load());o.add(list,BorderLayout.CENTER);o.add(detailCard(),BorderLayout.EAST);return o;}
 private JPanel detailCard(){detail.setPreferredSize(new Dimension(330,0));detail.setBackground(Color.WHITE);detail.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(0,0,12,0)));showEmpty();return detail;}
 private void showEmpty(){detail.removeAll();detail.add(head("TÀI KHOẢN","Chọn một dòng để xem chi tiết"),BorderLayout.NORTH);JLabel h=new JLabel("Rê chuột vào danh sách bên trái",SwingConstants.CENTER);h.setForeground(MainFrame.MUTED);detail.add(h,BorderLayout.CENTER);detail.revalidate();detail.repaint();}
 private JPanel head(String a,String b){JPanel h=new JPanel();h.setBackground(MainFrame.NAVY);h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));h.setBorder(BorderFactory.createEmptyBorder(16,18,16,18));JLabel x=new JLabel(a);x.setForeground(Color.WHITE);x.setFont(new Font("Segoe UI",Font.BOLD,13));JLabel y=new JLabel(b);y.setForeground(new Color(190,215,226));h.add(x);h.add(Box.createVerticalStrut(4));h.add(y);return h;}
 private void showDetail(AccountRow r){if(r==null||r==hovered)return;hovered=r;detail.removeAll();JPanel body=new JPanel();body.setBackground(Color.WHITE);body.setBorder(BorderFactory.createEmptyBorder(16,18,10,18));body.setLayout(new BoxLayout(body,BoxLayout.Y_AXIS));JLabel status=new JLabel(statusText(r.status()));status.setOpaque(true);status.setBackground("HoatDong".equals(r.status())?new Color(38,157,105):new Color(210,75,83));status.setForeground(Color.WHITE);status.setBorder(BorderFactory.createEmptyBorder(5,9,5,9));body.add(status);body.add(Box.createVerticalStrut(14));body.add(group("Thông tin tài khoản",new String[]{"Tên đăng nhập",safe(r.username()),"Nhân viên",safe(r.employeeId())+" - "+safe(r.employeeName()),"Vai trò",safe(r.roles()),"Ngày tạo",safe(r.createdAt())}));body.add(Box.createVerticalStrut(12));body.add(group("Hoạt động",new String[]{"Trạng thái",statusText(r.status()),"Đăng nhập gần nhất",safe(r.lastLoginAt())}));JScrollPane scroll=new JScrollPane(body);scroll.setBorder(null);JPanel actions=new JPanel(new GridLayout(1,2,8,0));actions.setBackground(Color.WHITE);actions.setBorder(BorderFactory.createEmptyBorder(10,18,0,18));UIStyle.secondaryButton(edit);UIStyle.dangerButton(toggle);edit.setEnabled(true);toggle.setEnabled(!"ThuHoi".equals(r.status()));JButton refresh=new JButton("Làm mới");UIStyle.secondaryButton(refresh);refresh.addActionListener(e->load());actions.add(refresh);actions.add(edit);actions.add(toggle);detail.add(head(r.username(),safe(r.employeeName())),BorderLayout.NORTH);detail.add(scroll,BorderLayout.CENTER);detail.add(actions,BorderLayout.SOUTH);detail.revalidate();detail.repaint();}
 private JPanel group(String title,String[] data){JPanel p=new JPanel();p.setOpaque(false);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel(title);h.setFont(new Font("Segoe UI",Font.BOLD,12));h.setForeground(MainFrame.TEXT);p.add(h);p.add(Box.createVerticalStrut(7));for(int i=0;i<data.length;i+=2){JPanel row=new JPanel(new BorderLayout(8,0));row.setOpaque(false);JLabel k=new JLabel(data[i]);k.setForeground(MainFrame.MUTED);JLabel v=new JLabel("<html>"+data[i+1]+"</html>");v.setForeground(MainFrame.TEXT);row.add(k,BorderLayout.WEST);row.add(v,BorderLayout.CENTER);p.add(row);p.add(Box.createVerticalStrut(5));}return p;}
 private static String safe(Object x){return x==null||x.toString().isBlank()?"Chưa cập nhật":x.toString();}private static String statusText(String s){return switch(s==null?"":s){case "HoatDong"->"Hoạt động";case "Khoa"->"Đã khóa";case "ChoKichHoat"->"Chờ kích hoạt";case "ThuHoi"->"Đã thu hồi";default->safe(s);};}
 private void open(AccountRow r){new AccountDialog(SwingUtilities.getWindowAncestor(this),session,bus,r).setVisible(true);load();}private void toggle(){if(hovered==null)return;String next="HoatDong".equals(hovered.status())?"Khoa":"HoatDong";if(JOptionPane.showConfirmDialog(this,("HoatDong".equals(next)?"Mở khóa":"Khóa")+" tài khoản '"+hovered.username()+"'?","Xác nhận",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{bus.changeStatus(session,hovered.id(),next);UIStyle.showSuccess(this,"Đã cập nhật trạng thái tài khoản.");load();}catch(RuntimeException e){UIStyle.showError(this,e.getMessage());}}
 private void load(){new SwingWorker<java.util.List<AccountRow>,Void>(){protected java.util.List<AccountRow> doInBackground(){String st=filter.getSelectedIndex()==0?"":(String)filter.getSelectedItem();return bus.search(session,search.getText(),st);}protected void done(){try{model.setRowCount(0);for(AccountRow r:get())model.addRow(new Object[]{r.id(),r.username(),r.employeeId()+" - "+r.employeeName(),r.roles(),statusText(r.status()),r.lastLoginAt(),r});hovered=null;showEmpty();}catch(Exception e){UIStyle.showError(AccountPanel.this,e.getCause()==null?e.getMessage():e.getCause().getMessage());}}}.execute();}
}
